INSERT INTO storage.buckets(id,name,public,allowed_mime_types) VALUES('property-images','property-images',true,ARRAY['image/jpeg','image/png','image/webp','video/mp4','video/webm']);
INSERT INTO storage.buckets(id,name,public,allowed_mime_types) VALUES('avatars','avatars',true,ARRAY['image/jpeg','image/png','image/webp']);
INSERT INTO storage.buckets(id,name,public,allowed_mime_types) VALUES('verification-docs','verification-docs',false,ARRAY['image/jpeg','image/png','image/webp','application/pdf']);
