CREATE POLICY property_images_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='property-images' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY property_images_update ON storage.objects FOR UPDATE TO authenticated USING(bucket_id='property-images' AND (storage.foldername(name))[1]=auth.uid()::text) WITH CHECK(bucket_id='property-images' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY property_images_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='property-images' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY property_images_read ON storage.objects FOR SELECT TO anon,authenticated USING(bucket_id='property-images');
CREATE POLICY avatars_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='avatars' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY avatars_update ON storage.objects FOR UPDATE TO authenticated USING(bucket_id='avatars' AND (storage.foldername(name))[1]=auth.uid()::text) WITH CHECK(bucket_id='avatars' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY avatars_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='avatars' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY avatars_read ON storage.objects FOR SELECT TO anon,authenticated USING(bucket_id='avatars');
CREATE POLICY verification_docs_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='verification-docs' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY verification_docs_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='verification-docs' AND ((storage.foldername(name))[1]=auth.uid()::text OR public.has_role(auth.uid(),'admin')));
CREATE POLICY payment_screenshots_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='payment-screenshots' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY payment_screenshots_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='payment-screenshots' AND ((storage.foldername(name))[1]=auth.uid()::text OR public.has_role(auth.uid(),'admin')));
CREATE POLICY property_documents_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='property-documents' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY property_documents_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='property-documents' AND ((storage.foldername(name))[1]=auth.uid()::text OR public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.property_documents d WHERE d.file_url=name AND prop_connect_private.can_read_document(d.property_id))));
CREATE POLICY chat_attachments_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='chat-attachments' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY chat_attachments_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='chat-attachments' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY chat_attachments_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='chat-attachments' AND prop_connect_private.can_read_chat_file(name));
